BEGIN;

CREATE TABLE IF NOT EXISTS privacy_policies (tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, version bigint NOT NULL, policy jsonb NOT NULL, fingerprint char(64) NOT NULL, updated_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tenant_id, version), UNIQUE (tenant_id, fingerprint));
CREATE INDEX IF NOT EXISTS privacy_policies_latest_idx ON privacy_policies(tenant_id, version DESC);
CREATE TABLE IF NOT EXISTS privacy_policy_snapshots (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, policy_version bigint NOT NULL, fingerprint char(64) NOT NULL, policy jsonb NOT NULL, execution_kind text NOT NULL, execution_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, execution_kind, execution_id), FOREIGN KEY (tenant_id, policy_version) REFERENCES privacy_policies(tenant_id, version) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS privacy_policy_snapshots_scope_idx ON privacy_policy_snapshots(tenant_id, created_at DESC);
CREATE TABLE IF NOT EXISTS privacy_classifications (tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, domain text NOT NULL, classification text NOT NULL CHECK (classification IN ('PUBLIC','INTERNAL','CONFIDENTIAL','SENSITIVE','RESTRICTED')), retention_days integer NOT NULL CHECK (retention_days >= 0), grace_days integer NOT NULL DEFAULT 7 CHECK (grace_days >= 0), encrypted_at_rest boolean NOT NULL DEFAULT false, redact_exports boolean NOT NULL DEFAULT true, allow_public_runner boolean NOT NULL DEFAULT false, immutable_evidence boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (tenant_id, domain));
CREATE TABLE IF NOT EXISTS privacy_holds (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, project_id text REFERENCES projects(id) ON DELETE SET NULL, reason text NOT NULL, scope jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, created_by text NOT NULL, released_by text, created_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz);
ALTER TABLE privacy_holds DROP CONSTRAINT IF EXISTS privacy_holds_project_id_fkey;
ALTER TABLE privacy_holds ADD CONSTRAINT privacy_holds_project_id_fkey FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS privacy_holds_scope_idx ON privacy_holds(tenant_id, project_id, active);
CREATE TABLE IF NOT EXISTS privacy_retention_runs (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, policy_snapshot_id text NOT NULL REFERENCES privacy_policy_snapshots(id) ON DELETE RESTRICT, status text NOT NULL CHECK (status IN ('RUNNING','PAUSED','COMPLETED','FAILED')), checkpoint jsonb, scanned bigint NOT NULL DEFAULT 0, eligible bigint NOT NULL DEFAULT 0, quarantined bigint NOT NULL DEFAULT 0, destroyed bigint NOT NULL DEFAULT 0, blocked bigint NOT NULL DEFAULT 0, last_error jsonb, started_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
ALTER TABLE privacy_retention_runs ALTER COLUMN checkpoint TYPE jsonb USING CASE WHEN checkpoint IS NULL THEN NULL ELSE checkpoint::jsonb END;
CREATE INDEX IF NOT EXISTS privacy_retention_runs_scope_idx ON privacy_retention_runs(tenant_id, updated_at DESC);
CREATE TABLE IF NOT EXISTS privacy_retention_items (id text PRIMARY KEY, run_id text NOT NULL REFERENCES privacy_retention_runs(id) ON DELETE RESTRICT, tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, project_id text, resource_type text NOT NULL, resource_id text NOT NULL, classification text NOT NULL, observed_at timestamptz NOT NULL, eligible_at timestamptz NOT NULL, policy_snapshot_id text NOT NULL REFERENCES privacy_policy_snapshots(id) ON DELETE RESTRICT, immutable_evidence boolean NOT NULL DEFAULT false, state text NOT NULL CHECK (state IN ('ELIGIBLE','QUARANTINED','APPROVED','DESTROYED','BLOCKED','PRESERVED')), quarantine_until timestamptz, approval_id text, reason text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, resource_type, resource_id, policy_snapshot_id));
CREATE INDEX IF NOT EXISTS privacy_retention_items_ready_idx ON privacy_retention_items(tenant_id, state, eligible_at, id);
CREATE TABLE IF NOT EXISTS privacy_operator_approvals (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, action text NOT NULL CHECK (action IN ('DESTROY_RETENTION_BATCH','DESTROY_TENANT','RELEASE_HOLD')), target_fingerprint char(64) NOT NULL, approved_by text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, action, target_fingerprint));
CREATE TABLE IF NOT EXISTS privacy_quarantine (id text PRIMARY KEY, retention_item_id text NOT NULL UNIQUE REFERENCES privacy_retention_items(id) ON DELETE RESTRICT, tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, resource_type text NOT NULL, resource_id text NOT NULL, storage_key text, encrypted_payload bytea, checksum char(64), quarantined_at timestamptz NOT NULL DEFAULT now(), purge_after timestamptz NOT NULL, state text NOT NULL CHECK (state IN ('QUARANTINED','PURGED','BLOCKED')));
CREATE TABLE IF NOT EXISTS privacy_decision_evidence (id bigserial PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT, retention_item_id text REFERENCES privacy_retention_items(id) ON DELETE RESTRICT, actor text NOT NULL, decision text NOT NULL, reason text NOT NULL, policy_snapshot_id text, hold_ids jsonb NOT NULL DEFAULT '[]'::jsonb, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS privacy_decision_evidence_scope_idx ON privacy_decision_evidence(tenant_id, created_at DESC);
ALTER TABLE lifecycle_holds ADD COLUMN IF NOT EXISTS privacy_hold_id text;

INSERT INTO privacy_policies(tenant_id,version,policy,fingerprint,updated_by)
SELECT t.id,1,'{"defaultDays":365,"graceDays":7,"domains":{"audit_evidence":{"retentionDays":0,"immutableEvidence":true,"redactExports":true,"encryptedAtRest":true,"allowPublicRunner":false},"provenance":{"retentionDays":730,"immutableEvidence":true,"redactExports":true,"encryptedAtRest":true,"allowPublicRunner":false},"artifacts":{"retentionDays":90,"graceDays":7,"encryptedAtRest":true,"redactExports":true,"allowPublicRunner":false},"job_logs":{"retentionDays":30,"graceDays":7,"redactExports":true},"event_payloads":{"retentionDays":180,"graceDays":14,"encryptedAtRest":true,"redactExports":true},"provider_payloads":{"retentionDays":30,"graceDays":7,"encryptedAtRest":true,"redactExports":true,"allowPublicRunner":false},"webhook_envelopes":{"retentionDays":30,"graceDays":7,"encryptedAtRest":true,"redactExports":true},"publish_metadata":{"retentionDays":365,"graceDays":30,"encryptedAtRest":true,"redactExports":true},"reviews_comments":{"retentionDays":365,"graceDays":30,"encryptedAtRest":true,"redactExports":true},"backups":{"retentionDays":365,"graceDays":30,"immutableEvidence":true,"encryptedAtRest":true,"redactExports":true,"allowPublicRunner":false}}}'::jsonb,'a7bc7092a184b00773165c3aa1792562b248042d59e0b866ac565c4947f2e346','migration-023'
FROM tenants t ON CONFLICT (tenant_id,version) DO NOTHING;
INSERT INTO privacy_classifications(tenant_id, domain, classification, retention_days, grace_days, encrypted_at_rest, redact_exports, allow_public_runner, immutable_evidence)
SELECT t.id, d.domain, d.classification, d.retention_days, d.grace_days, d.encrypted_at_rest, d.redact_exports, d.allow_public_runner, d.immutable_evidence FROM tenants t CROSS JOIN (VALUES ('audit_evidence','RESTRICTED',0,0,true,true,false,true),('provenance','CONFIDENTIAL',730,30,true,true,false,true),('artifacts','SENSITIVE',90,7,true,true,false,false),('job_logs','INTERNAL',30,7,false,true,false,false),('event_payloads','SENSITIVE',180,14,true,true,false,false),('provider_payloads','RESTRICTED',30,7,true,true,false,false),('webhook_envelopes','SENSITIVE',30,7,true,true,false,false),('publish_metadata','CONFIDENTIAL',365,30,true,true,false,false),('reviews_comments','CONFIDENTIAL',365,30,true,true,false,false),('backups','RESTRICTED',365,30,true,true,false,true)) d(domain,classification,retention_days,grace_days,encrypted_at_rest,redact_exports,allow_public_runner,immutable_evidence) ON CONFLICT (tenant_id, domain) DO NOTHING;
INSERT INTO privacy_holds(id,tenant_id,project_id,reason,created_by,created_at) SELECT COALESCE(l.privacy_hold_id,l.id),l.tenant_id,l.project_id,l.reason,l.created_by,l.created_at FROM lifecycle_holds l WHERE l.active AND l.kind='LEGAL' ON CONFLICT(id) DO UPDATE SET active=true,reason=EXCLUDED.reason;

CREATE OR REPLACE FUNCTION forge_privacy_hold_guard() RETURNS trigger AS $$
BEGIN
  IF NEW.active AND NEW.kind = 'LEGAL' THEN INSERT INTO privacy_holds(id,tenant_id,project_id,reason,created_by) VALUES (COALESCE(NEW.privacy_hold_id, NEW.id),NEW.tenant_id,NEW.project_id,NEW.reason,NEW.created_by) ON CONFLICT(id) DO UPDATE SET active=true, reason=EXCLUDED.reason; END IF;
  IF NOT NEW.active AND OLD.active THEN UPDATE privacy_holds SET active=false,released_by=NEW.released_by,released_at=COALESCE(NEW.released_at,now()) WHERE id=COALESCE(NEW.privacy_hold_id,NEW.id); END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_privacy_hold_sync ON lifecycle_holds;
CREATE TRIGGER forge_privacy_hold_sync AFTER INSERT OR UPDATE OF active ON lifecycle_holds FOR EACH ROW EXECUTE FUNCTION forge_privacy_hold_guard();
COMMIT;
